#!/usr/bin/env python3
"""
market_advisor 一键热修复脚本 v1.0
===================================
功能：
1. 自动覆盖所有 .py 文件为最新版本
2. 修复数据库（创建缺失的 akshare_limit_up 表）
3. 验证修复结果

使用方法：
1. 将本文件放到 market_advisor 目录下
2. 运行: python hotfix.py
3. 重启服务: python app.py
"""
import os
import sys
import zipfile
import io
import base64
import zlib
import sqlite3
import traceback

# ============================================================
# 第一步：解压并覆盖所有 .py 文件
# ============================================================
ENCODED_DATA = """

"""

def step1_update_files():
    print("=" * 60)
    print("[步骤1] 解压并更新所有 .py 文件...")
    print("=" * 60)
    
    script_dir = os.path.dirname(os.path.abspath(__file__))
    print(f"目标目录: {script_dir}")
    
    try:
        compressed = base64.b64decode(ENCODED_DATA.strip())
        zip_data = zlib.decompress(compressed)
        buf = io.BytesIO(zip_data)
        
        updated = []
        with zipfile.ZipFile(buf, 'r') as zf:
            for name in zf.namelist():
                if name.endswith('.py'):
                    target = os.path.join(script_dir, name)
                    # Backup old file
                    if os.path.exists(target):
                        backup = target + '.bak'
                        with open(target, 'rb') as f:
                            old_content = f.read()
                        with open(backup, 'wb') as f:
                            f.write(old_content)
                    # Write new file
                    with zf.open(name) as src, open(target, 'wb') as dst:
                        dst.write(src.read())
                    updated.append(name)
        
        print(f"  已更新 {len(updated)} 个文件:")
        for f in updated:
            print(f"    -> {f}")
        print()
        return True
    except Exception as e:
        print(f"  X 文件更新失败: {e}")
        traceback.print_exc()
        return False


# ============================================================
# 第二步：修复数据库
# ============================================================
def get_db_path():
    script_dir = os.path.dirname(os.path.abspath(__file__))
    parent_dir = os.path.dirname(script_dir)
    return os.path.join(parent_dir, "stock_data_1784791326780_0_09ym.db")


def step2_fix_database():
    print("=" * 60)
    print("[步骤2] 修复数据库...")
    print("=" * 60)
    
    db_path = get_db_path()
    print(f"数据库路径: {db_path}")
    
    if not os.path.exists(db_path):
        print(f"  X 数据库文件不存在!")
        return False
    
    print(f"  文件大小: {os.path.getsize(db_path) / 1024:.2f} KB")
    
    try:
        conn = sqlite3.connect(db_path, isolation_level=None)
        cursor = conn.cursor()
        
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
        existing_tables = [row[0] for row in cursor.fetchall()]
        print(f"  当前表数量: {len(existing_tables)}")
        
        if 'akshare_limit_up' not in existing_tables:
            print("  创建 akshare_limit_up 表...")
            cursor.execute("""
                CREATE TABLE akshare_limit_up (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    date TEXT NOT NULL,
                    code TEXT NOT NULL,
                    name TEXT,
                    continuous_boards INTEGER DEFAULT 1,
                    seal_amount REAL,
                    seal_style TEXT,
                    turnover_rate REAL,
                    latest_price REAL,
                    change_percent REAL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(date, code)
                )
            """)
            print("  [OK] akshare_limit_up 表创建成功")
        else:
            print("  [OK] akshare_limit_up 表已存在")
        
        other_tables = {
            'xgb_limit_up_detail': "CREATE TABLE IF NOT EXISTS xgb_limit_up_detail (date TEXT, code TEXT, name TEXT, concept TEXT, reason TEXT, UNIQUE(date, code))",
            'concept_statistics': "CREATE TABLE IF NOT EXISTS concept_statistics (date TEXT, concept TEXT, count INTEGER, UNIQUE(date, concept))",
            'smash_coefficient_results': "CREATE TABLE IF NOT EXISTS smash_coefficient_results (date TEXT PRIMARY KEY, smash_coefficient REAL, max_continuous_boards INTEGER)",
            'prediction_records': "CREATE TABLE IF NOT EXISTS prediction_records (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT, prediction_type TEXT, content TEXT, confidence REAL, actual_result TEXT, accuracy_score REAL, verified INTEGER DEFAULT 0)",
            'model_weights': "CREATE TABLE IF NOT EXISTS model_weights (factor_name TEXT PRIMARY KEY, weight REAL, history TEXT, consecutive_misses INTEGER DEFAULT 0, credibility REAL DEFAULT 1.0)",
            'market_knowledge': "CREATE TABLE IF NOT EXISTS market_knowledge (id INTEGER PRIMARY KEY AUTOINCREMENT, pattern_type TEXT, description TEXT, occurrence_count INTEGER DEFAULT 1, success_rate REAL DEFAULT 0.5)",
            'correction_log': "CREATE TABLE IF NOT EXISTS correction_log (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT, trigger TEXT, factor_name TEXT, old_weight REAL, new_weight REAL, reason TEXT)",
            'daily_snapshot': "CREATE TABLE IF NOT EXISTS daily_snapshot (date TEXT PRIMARY KEY, limit_up_count INTEGER, max_continuous_boards INTEGER, avg_seal_amount REAL, smash_coefficient REAL, market_phase TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)",
            'backtest_records': "CREATE TABLE IF NOT EXISTS backtest_records (id INTEGER PRIMARY KEY AUTOINCREMENT, backtest_date TEXT, target_date TEXT, prediction_type TEXT, predicted_value REAL, actual_value REAL)"
        }
        
        for table_name, create_sql in other_tables.items():
            if table_name not in existing_tables:
                cursor.execute(create_sql)
                print(f"  [OK] {table_name} 表创建成功")
        
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
        final_tables = [row[0] for row in cursor.fetchall()]
        print(f"  最终表数量: {len(final_tables)}")
        
        required = ['akshare_limit_up', 'xgb_limit_up_detail', 'concept_statistics',
                     'smash_coefficient_results', 'prediction_records', 'model_weights',
                     'market_knowledge', 'correction_log', 'daily_snapshot', 'backtest_records']
        
        all_ok = True
        for t in required:
            if t in final_tables:
                print(f"    [OK] {t}")
            else:
                print(f"    [FAIL] {t}")
                all_ok = False
        
        cursor.execute("SELECT COUNT(*) FROM akshare_limit_up")
        count = cursor.fetchone()[0]
        print(f"  akshare_limit_up 数据量: {count} 条")
        
        conn.close()
        
        if all_ok:
            print("  [OK] 数据库修复完成")
        else:
            print("  [WARN] 部分表仍缺失")
        
        return all_ok
        
    except Exception as e:
        print(f"  [FAIL] 数据库修复失败: {e}")
        traceback.print_exc()
        return False


# ============================================================
# 第三步：验证文件版本
# ============================================================
def step3_verify():
    print("=" * 60)
    print("[步骤3] 验证文件版本...")
    print("=" * 60)
    
    script_dir = os.path.dirname(os.path.abspath(__file__))
    db_path = os.path.join(script_dir, 'db.py')
    
    if not os.path.exists(db_path):
        print("  [FAIL] db.py 不存在!")
        return False
    
    with open(db_path, 'r', encoding='utf-8') as f:
        content = f.read()
    
    checks = {
        'isolation_level=None': 'isolation_level=None' in content,
        'akshare_limit_up建表': 'akshare_limit_up' in content and 'CREATE TABLE' in content,
    }
    
    all_ok = True
    for check_name, result in checks.items():
        status = "OK" if result else "FAIL"
        print(f"  [{status}] db.py - {check_name}")
        if not result:
            all_ok = False
    
    main_path = os.path.join(script_dir, 'main.py')
    if os.path.exists(main_path):
        with open(main_path, 'r', encoding='utf-8') as f:
            main_content = f.read()
        has_step = 'Step -1' in main_content or 'run_fetch' in main_content
        status = "OK" if has_step else "FAIL"
        print(f"  [{status}] main.py - 自动获取逻辑")
        if not has_step:
            all_ok = False
    
    return all_ok


# ============================================================
# 主流程
# ============================================================
if __name__ == '__main__':
    print()
    print("=" * 60)
    print("  market_advisor 一键热修复 v1.0")
    print("=" * 60)
    print()
    
    r1 = step1_update_files()
    print()
    r2 = step2_fix_database()
    print()
    r3 = step3_verify()
    
    print()
    print("=" * 60)
    if r1 and r2 and r3:
        print("  ALL DONE! 所有修复完成!")
        print()
        print("  下一步操作:")
        print("  1. 关闭当前 app.py (Ctrl+C)")
        print("  2. 重新启动: python app.py")
        print("  3. 在网页中点击 获取数据 然后 每日分析")
        print()
        print("  启动后应该看到:")
        print("  - 10次 表创建/验证成功")
        print("  - 所有10张表验证通过")
    else:
        print("  WARN: 部分修复未完成，请检查上方错误信息")
    print("=" * 60)
    print()
